-- 4b. The report
-- READ-ONLY
--
-- GENERATED from 590-proquest-ebc-batch-removal/README.md by tools/Build-SolutionDocs.ps1.
-- Do not edit this file - edit the README and re-run the script.
-- The README carries the reasoning, review gates and caveats.

SELECT
    r.[bib#] AS [bib#],
    STUFF((
        SELECT ' ;; ' + x.ebc
        FROM (
            SELECT
                s.tagord,
                LEFT(s.frag, 2 + PATINDEX('%[^0-9]%', SUBSTRING(s.frag, 4, 255) + 'x')) AS ebc
            FROM (
                SELECT
                    e.tagord,
                    SUBSTRING(e.text,
                              PATINDEX('%EBC[0-9]%', e.text COLLATE Latin1_General_CS_AS),
                              255) AS frag
                FROM bib e
                WHERE e.[bib#] = r.[bib#]
                  AND e.tag = '035'
                  AND e.text COLLATE Latin1_General_CS_AS LIKE '%EBC[0-9]%'
            ) s
        ) x
        GROUP BY x.ebc
        ORDER BY MIN(x.tagord)
        FOR XML PATH('')
    ), 1, 4, '') AS [EBC_035],
    REPLACE(REPLACE(REPLACE(STUFF((
        SELECT ' ;; ' + REPLACE(REPLACE(COALESCE(n.text, CAST(nl.longtext AS varchar(8000))),
                                        CHAR(31), '|'), CHAR(30), '')
        FROM bib n
        LEFT JOIN bib_longtext nl
               ON nl.[bib#] = n.[bib#] AND nl.tag = n.tag AND nl.tagord = n.tagord
        WHERE n.[bib#] = r.[bib#]
          AND n.tag = '590'
        ORDER BY n.tagord
        FOR XML PATH('')
    ), 1, 4, ''), '&lt;', '<'), '&gt;', '>'), '&amp;', '&') AS [590_fields]
FROM (
    SELECT DISTINCT b.[bib#]
    FROM bib b
    WHERE b.tag = '035'
      AND b.text COLLATE Latin1_General_CS_AS LIKE '%EBC[0-9]%'
) r
ORDER BY r.[bib#];
